// Author: MiYu. Focused native drawing/input checks for map browsing and setup controls.
#include "map_browser.h"
#include <StormLib.h>
#include <functional>
#include <iostream>

using namespace war3;
namespace {
void require(bool value,const char* message) {if(!value)throw std::runtime_error(message);}
UiInput key(unsigned code,bool shift=false) {UiInput i;i.x=i.y=-1;i.key=code;i.shift=shift;return i;}
UiInput click(float x,float y,bool twice=false) {UiInput i;i.x=i.startX=x;i.y=i.startY=y;i.pressed=true;i.doubleClick=twice;return i;}
UiInput click(GlueScreen::Rect r) {return click(r.x+r.w/2,r.y+r.h/2);}
void mapArchive(const fs::path& path,const std::string& member,const std::string& value) {
    HANDLE archive=nullptr;require(SFileCreateArchive(path.c_str(),MPQ_CREATE_ARCHIVE_V1,32,&archive),"Cannot create map fixture");
    struct Close {HANDLE value;~Close(){SFileCloseArchive(value);}} close{archive};HANDLE file=nullptr;require(SFileCreateFile(archive,member.c_str(),0,DWORD(value.size()),0,0,&file),"Cannot create fixture member");bool written=SFileWriteFile(file,value.data(),DWORD(value.size()),0),finished=SFileFinishFile(file);require(written && finished,"Cannot write map fixture");
}
ULONG references(IDirect3DTexture9* texture) {texture->AddRef();return texture->Release();}
}
int wmain(int argc,wchar_t** argv) {
    if(argc!=3){std::cerr<<"Usage: war3_browser_tests <data-root> <scratch-root>\n";return 2;}
    unsigned passed=0,failed=0;auto test=[&](const char* name,const std::function<void()>& run){try{run();++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cout<<"FAIL "<<name<<": "<<e.what()<<'\n';}};
    try {
        auto dataRoot=fs::canonical(argv[1]),output=fs::absolute(argv[2]);fs::create_directories(output);auto scratch=output/(std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64()));require(!fs::exists(scratch),"Scratch already exists");fs::create_directories(scratch/L"Folder");fs::create_directory(scratch/L"Vanishing");
        auto source=dataRoot/L"Maps/(2)BootyBay.w3m",valid=scratch/L"a-valid.w3m",bad=scratch/L"b-bad.w3x",missing=scratch/L"c-missing.w3x",truncated=scratch/L"d-truncated.w3x";fs::copy_file(source,valid);{std::ofstream file(bad,std::ios::binary);file<<"broken archive";}mapArchive(missing,"other.txt","not a map");mapArchive(truncated,"war3map.w3i","short");
        WNDCLASSW type{};type.hInstance=GetModuleHandleW(nullptr);type.lpfnWndProc=DefWindowProcW;type.lpszClassName=L"War3BrowserChecks";require(RegisterClassW(&type)!=0,"Cannot register check window");auto window=CreateWindowW(type.lpszClassName,L"War3 UI checks",WS_OVERLAPPEDWINDOW,0,0,1280,960,nullptr,nullptr,type.hInstance,nullptr);require(window!=nullptr,"Cannot create check window");struct Close {HWND value;~Close(){DestroyWindow(value);}} close{window};
        Renderer renderer(window);Archives archives(dataRoot);Images images(dataRoot);auto font=archives.read(skinValue(archives,"MasterFont","Fonts\\FRIZQT__.TTF"));require(bool(font),"Missing font");Text text(renderer,font->bytes);Log log(output/L"browser-events.log");std::cout<<"DRIVER "<<renderer.driver()<<" fixture="<<utf8(scratch.wstring())<<'\n';
        auto render=[&](const std::function<void()>& draw,const fs::path& capture=fs::path{}){MSG message;while(PeekMessageW(&message,nullptr,0,0,PM_REMOVE)){TranslateMessage(&message);DispatchMessageW(&message);}require(renderer.begin(),"Device unavailable during check");draw();require(renderer.end(capture),"Present failed during check");renderer.device()->SetTexture(0,nullptr);};
        MapBrowser browser(archives,images,renderer,text,log,dataRoot,valid);
        auto browse=[&](const UiInput& input=UiInput{},const fs::path& capture=fs::path{}){std::string action;render([&]{action=browser.draw(input);},capture);return action;};
        auto choose=[&](const fs::path& path){auto found=std::find_if(browser.entries().begin(),browser.entries().end(),[&](auto& e){return e.path==path;});require(found!=browser.entries().end(),"Fixture missing from directory");auto index=size_t(found-browser.entries().begin());browse(key(VK_HOME));for(size_t i=0;i<index;++i)browse(key(VK_DOWN));};
        test("browser_source_map_and_preview",[&]{browse();require(browser.info() && browser.setup() && browser.preview() && browser.selectedMap()==valid,"Initial map/preview unavailable");require(browser.setup()->localPlayer()==0u,"Booty Bay local source ID differs");});
        test("browser_directory_double_click_and_parent",[&]{choose(scratch/L"Folder");auto [x,y]=browser.selectedCenter();browse(click(x,y,true));require(browser.directory()==scratch/L"Folder" && !browser.info() && !browser.setup() && !browser.preview(),"Double-click did not enter folder or clear map");browse(key(VK_RETURN));require(browser.directory()==scratch,"Parent entry Enter did not return");choose(scratch/L"Folder");browse(key(VK_RETURN));require(browser.directory()==scratch/L"Folder","Folder Enter failed");browse(key(VK_BACK));require(browser.directory()==scratch,"Backspace did not return");});
        test("browser_bad_map_releases_preview_and_retries",[&]{choose(valid);require(browser.preview()!=nullptr,"Preview missing before failure");Com<IDirect3DTexture9> old=browser.preview();auto before=references(old.Get());auto current=std::find_if(browser.entries().begin(),browser.entries().end(),[&](auto& e){return e.path==valid;});require(current!=browser.entries().end() && std::next(current)!=browser.entries().end() && std::next(current)->path==bad,"Failure fixture is not adjacent to valid map");browse(key(VK_DOWN));require(!browser.info() && !browser.setup() && !browser.preview() && browser.selectedMap().empty() && !browser.error().empty(),"Bad map retained partial selection");require(references(old.Get())+1==before,"Old preview node reference retained");fs::copy_file(source,bad,fs::copy_options::overwrite_existing);auto [x,y]=browser.selectedCenter();browse(click(x,y));require(browser.info() && browser.setup() && browser.preview() && browser.error().empty() && browser.selectedMap()==bad,"Same-map retry did not recover");});
        test("browser_missing_and_truncated_map_recovery",[&]{for(auto path:{missing,truncated}){choose(path);require(!browser.error().empty() && !browser.info() && !browser.setup() && !browser.preview(),"Malformed map retained usable data");choose(valid);require(browser.info() && browser.setup() && browser.error().empty(),"Valid map did not recover selection");}});
        test("browser_stale_directory_recovery",[&]{auto folder=scratch/L"Vanishing";choose(folder);require(fs::remove(folder),"Cannot remove empty owned fixture folder");auto [x,y]=browser.selectedCenter();browse(click(x,y,true));require(browser.directory()==scratch && !browser.error().empty() && !browser.info() && !browser.preview(),"Stale directory was not contained");fs::create_directory(folder);browse(click(x,y,true));require(browser.directory()==folder && browser.error().empty(),"Recreated directory did not recover");browse(key(VK_BACK));});
        test("browser_popup_blocks_underlying_map_input",[&]{choose(valid);auto r=browser.bounds("player-0/HandicapMenu");browse(click(r));require(browser.popupOpen(),"Browser popup did not open");auto selected=browser.selectedMap();auto [x,y]=browser.selectedCenter();browse(click(x,y));require(!browser.popupOpen() && browser.selectedMap()==selected && browser.focus()=="player-0/HandicapMenu","Outside popup click reached map list");browse(click(r));browse(key(VK_ESCAPE));require(!browser.popupOpen() && browser.selectedMap()==selected,"Popup Escape cancelled browser");browse(UiInput{},output/L"browser-recovered.png");});
        GlueScreen screen(archives,images,renderer,text,"UI\\FrameDef\\Glue\\Skirmish.fdf","Skirmish");screen.visible("AdvancedOptionsPanel",false);PlayerSetupUi ui(screen);MapInfo model;for(int i=0;i<16;++i)model.players.push_back({i,1,1,0,"",{},0,0});PlayerSetup setup(model);ui.bind(&setup);
        auto drawSetup=[&](const UiInput& input=UiInput{},const fs::path& capture=fs::path{}){ui.input(input);auto enabled=ui.enabled();enabled.insert("CancelButton");render([&]{screen.draw("Skirmish",input,enabled,true);ui.changed();ui.headings();screen.overlay();},capture);};
        FrameDefinitions definitions;definitions.load(archives,"UI\\FrameDef\\Glue\\PlayerSlot.fdf");auto menu=definitions.frame("StandardPopupMenuMenuTemplate");float border=menu.number("MenuBorder"),step=menu.number("MenuItemHeight");
        auto mouseChoice=[&](const std::string& name,size_t item){drawSetup(click(screen.bounds(name)));auto menu=screen.popupBounds();require(bool(menu),"Mouse did not open setup choice");require(menu->y>=0 && menu->y+menu->h<=.60001f,"Popup outside UI bounds");drawSetup(click(menu->x+menu->w/2,menu->y+border+(float(item)+.5f)*step));require(!screen.popupOpen(),"Mouse did not accept popup choice");};
        test("setup_mouse_fields_and_local_move",[&]{mouseChoice("player-1/NameMenu",4);require(setup.find(1)->control==SlotControl::ComputerNormal,"AI mouse choice differs");mouseChoice("player-1/RaceMenu",2);require(setup.find(1)->race==2,"Race mouse choice differs");mouseChoice("player-1/TeamButton",0);require(setup.find(1)->team==0,"Team mouse choice differs");mouseChoice("player-1/ColorButton",0);require(setup.find(1)->color==0 && setup.find(0)->color==1,"Color mouse choice did not swap");mouseChoice("player-1/HandicapMenu",2);require(setup.find(1)->handicap==80,"Handicap mouse choice differs");mouseChoice("player-1/NameMenu",0);require(setup.localPlayer()==1u && setup.find(0)->control==SlotControl::Open,"Mouse local move failed");});
        test("setup_forward_and_reverse_focus",[&]{std::vector<std::string> order;drawSetup();auto first=screen.focus();require(!first.empty(),"No focusable setup controls");for(unsigned i=0;i<128;++i){require(std::find(order.begin(),order.end(),screen.focus())==order.end(),"Forward focus entered secondary cycle");order.push_back(screen.focus());drawSetup(key(VK_TAB));if(screen.focus()==first)break;}require(order.size()>8 && screen.focus()==first,"Forward focus did not wrap");for(size_t i=order.size();i>0;--i){drawSetup(key(VK_TAB,true));require(screen.focus()==order[i-1],"Reverse focus is not forward traversal inverse");}});
        test("setup_popup_wheel_keyboard_and_stationary_mouse",[&]{drawSetup(click(screen.bounds("player-1/HandicapMenu")));require(screen.popupOpen(),"Handicap popup unavailable");auto area=*screen.popupBounds();UiInput hover;hover.x=area.x+area.w/2;hover.y=area.y+border+step/2;drawSetup(hover);auto down=hover;down.key=VK_DOWN;drawSetup(down);auto accept=hover;accept.key=VK_RETURN;drawSetup(accept);require(setup.find(1)->handicap==90,"Stationary mouse overrode keyboard popup focus");drawSetup(click(screen.bounds("player-1/HandicapMenu")));UiInput wheel;wheel.x=wheel.y=-1;wheel.wheel=-1;drawSetup(wheel);drawSetup(key(VK_RETURN));require(setup.find(1)->handicap==80,"Popup wheel did not select next value");});
        test("setup_long_list_scroll_and_bottom_popup",[&]{require(!ui.enabled().contains("player-15/NameMenu"),"Long list initially shows clipped row");auto r=screen.bounds("TeamSetupContainer");UiInput wheel;wheel.x=r.x+r.w/2;wheel.y=r.y+r.h/2;wheel.wheel=-16;drawSetup(wheel);require(ui.enabled().contains("player-15/NameMenu") && !ui.enabled().contains("player-0/NameMenu"),"Player list did not scroll");mouseChoice("player-15/NameMenu",5);require(setup.find(15)->control==SlotControl::ComputerInsane,"Bottom-row popup selection failed");drawSetup(UiInput{},output/L"setup-scrolled.png");});
        test("setup_fixed_settings_and_rebind",[&]{model.flags=0x60;model.forces={{3,0x00ff,"First"},{3,0xff00,"Second"}};PlayerSetup fixed(model);ui.bind(&fixed);drawSetup();require(!ui.enabled().contains("player-0/RaceMenu") && !ui.enabled().contains("player-0/ColorButton") && !ui.enabled().contains("player-0/TeamButton"),"Fixed settings controls editable");drawSetup(click(screen.bounds("player-0/RaceMenu")));require(!screen.popupOpen(),"Disabled race opened menu");mouseChoice("player-0/HandicapMenu",1);require(fixed.find(0)->handicap==90,"Fixed-map handicap edit unavailable");ui.bind(nullptr);drawSetup();require(ui.enabled().empty() && !screen.popupOpen(),"Cleared setup retained controls");ui.bind(&setup);drawSetup();require(setup.localPlayer()==1u && setup.find(1)->handicap==80,"Rebind discarded existing draft");});
        require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded into native UI checks");std::ofstream summary(output/L"browser-results.json",std::ios::binary);summary<<"{\"passed\":"<<passed<<",\"failed\":"<<failed<<",\"gameDllLoaded\":false,\"driver\":\""<<renderer.driver()<<"\"}";
    }catch(const std::exception& e){std::cout<<"SETUP "<<e.what()<<'\n';return 2;}
    std::cout<<"RESULT passed="<<passed<<" failed="<<failed<<'\n';return failed?1:0;
}
